mapper.select:
SELECT TRANSLATION_GROUP , TRANSLATION_TYPE , TRANSLATION_CODE , TRANSLATION_LOCALE , TRANSLATION_CONTENT , DATA_STATUS , CREATED_BY , CREATED_AT , UPDATED_BY , UPDATED_AT FROM TRANSLATION WHERE TRUE
AND TRANSLATION_GROUP = #{translationGroup}
AND TRANSLATION_TYPE = #{translationType}
AND TRANSLATION_CODE LIKE CONCAT('%', #{translationCode}, '%')
AND TRANSLATION_LOCALE = #{translationLocale}
AND DATA_STATUS = #{dataStatus}
AND CONCAT(TRANSLATION_GROUP, '.', TRANSLATION_TYPE, '.', TRANSLATION_CODE) LIKE CONCAT('%', #{translationKey}, '%')
ORDER BY TRANSLATION_GROUP, TRANSLATION_TYPE, TRANSLATION_CODE, TRANSLATION_LOCALE

mapper.insert:
INSERT INTO TRANSLATION (
    TRANSLATION_GROUP
  , TRANSLATION_TYPE
  , TRANSLATION_CODE
  , TRANSLATION_LOCALE
  , TRANSLATION_CONTENT
  , DATA_STATUS
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{translationGroup}
  , #{translationType}
  , #{translationCode}
  , #{translationLocale}
  , #{translationContent}
  , #{dataStatus}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TRANSLATION
   SET TRANSLATION_CONTENT = #{translationContent}
     , DATA_STATUS         = #{dataStatus}
     , UPDATED_BY          = #{author}
     , UPDATED_AT          = NOW()
 WHERE TRANSLATION_GROUP   = #{translationGroup}
   AND TRANSLATION_TYPE    = #{translationType}
   AND TRANSLATION_CODE    = #{translationCode}
   AND TRANSLATION_LOCALE  = #{translationLocale}

mapper.delete:
DELETE FROM TRANSLATION
 WHERE TRANSLATION_GROUP  = #{translationGroup}
   AND TRANSLATION_TYPE   = #{translationType}
   AND TRANSLATION_CODE   = #{translationCode}
   AND TRANSLATION_LOCALE = #{translationLocale}
